 // Módulo de stock (RF-003): existencia por SKU a partir de los eventos del contrato.
 import { crearStockAjustado, validarEvento } from "../../contratos/eventos.mjs";

-export function ajustarStock({ id, fecha, sku, delta, motivo }) {
-  return crearStockAjustado({ id, fecha, sku: String(sku).trim().toUpperCase(), delta, motivo });
+export function ajustarStock({ id, fecha, sku, delta, motivo, almacen }) {
+  return crearStockAjustado({ id, fecha, sku: String(sku).trim().toUpperCase(), delta, motivo, almacen });
+}
+
+const ALMACEN_POR_DEFECTO = "ALM-01";
+
+// RF-006: existencia por almacén. Ajustes sin almacén y ventas cuentan en ALM-01. Devuelve { [almacen]: { [sku]: unidades } }.
+export function stockPorAlmacen(eventos) {
+  const resultado = {};
+  const sumar = (almacen, sku, unidades) => {
+    resultado[almacen] ??= {};
+    resultado[almacen][sku] = (resultado[almacen][sku] ?? 0) + unidades;
+  };
+  for (const e of eventos.map(validarEvento)) {
+    if (e.tipo === "stock.ajustado") sumar(e.almacen ?? ALMACEN_POR_DEFECTO, e.sku, e.delta);
+    if (e.tipo === "venta.registrada") sumar(ALMACEN_POR_DEFECTO, e.sku, -e.cantidad);
+  }
+  return resultado;
 }

