+import { test } from "node:test";
+import assert from "node:assert/strict";
+import { ajustarStock, stockPorAlmacen } from "../../modulos/stock/stock.mjs";
+import { crearVentaRegistrada } from "../../contratos/eventos.mjs";
+
+test("RF-006: existencia por almacén; sin almacén y ventas cuentan en ALM-01", () => {
+  const eventos = [
+    ajustarStock({ id: "S-1", fecha: "2026-11-01", sku: "cafe-250", delta: 20, motivo: "compra" }),
+    ajustarStock({ id: "S-2", fecha: "2026-11-01", sku: "CAFE-250", delta: 10, motivo: "compra", almacen: "ALM-02" }),
+    ajustarStock({ id: "S-3", fecha: "2026-11-01", sku: "TE-100", delta: 5, motivo: "compra", almacen: "ALM-01" }),
+    crearVentaRegistrada({ id: "V-1", fecha: "2026-11-02", sku: "CAFE-250", cantidad: 3, precioUnitarioCentavos: 4500, canal: "web" }),
+  ];
+  assert.deepEqual(stockPorAlmacen(eventos), { "ALM-01": { "CAFE-250": 17, "TE-100": 5 }, "ALM-02": { "CAFE-250": 10 } });
+  assert.deepEqual(stockPorAlmacen([]), {});
+});
